import * as ID from "/vendor/netlify-identity.js";
const LOGO="/assets/logo.webp";
const coin=(c,y,s,sd,fd,pos)=>`<div class="cn ${c}" style="--s:${s}px;--sd:${sd}s;--fd:${fd}s;${pos}"><div class="ci"><span class="m" style="transform:translateZ(-2px)"></span><span class="m" style="transform:translateZ(2px)"></span><span class="f">${y}</span><span class="b">${y}</span></div></div>`;
const spray=[0,.18,.36,.54,.72].map(d=>`<i class="sp" style="animation-delay:${d}s"></i>`).join('');
const ski=(c)=>`<div class="skw ${c}"><div class="wk"></div><div class="skb"><svg viewBox="0 0 120 60"><use href="#ski" width="120" height="60"/></svg></div>${spray}</div>`;
const WAVE='M0 30 Q75 0 150 30 T300 30 T450 30 T600 30 T750 30 T900 30 T1050 30 T1200 30 V60 H0Z';
const SCENE=`<div class="scene" aria-hidden="true"><svg width="0" height="0" style="position:absolute"><defs>
<linearGradient id="hull" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#b9d2e4"/></linearGradient>
<linearGradient id="jf" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".6" stop-color="#e3edf4"/><stop offset="1" stop-color="#9db4c6"/></linearGradient>
<symbol id="ski" viewBox="0 0 120 60"><path d="M3 46Q28 56 72 53L112 42Q118 37 108 35L62 38Q44 26 30 32L10 40Z" fill="url(#hull)"/><path d="M24 36L66 37L92 41L72 47L20 45Z" fill="#f5b82e"/><path d="M30 31Q48 25 64 34L60 38L30 38Z" fill="#12243a"/><path d="M84 36Q104 36 112 42L88 45Z" fill="#fff"/><circle cx="38" cy="13" r="5" fill="#d9a77f"/><path d="M33 21Q40 18 46 22L45 34L33 34Z" fill="#ff8264"/><path d="M50 34L46 44" stroke="#12243a" stroke-width="4" stroke-linecap="round"/><path d="M46 20Q54 16 62 21L60 34L48 34Z" fill="#19c3d6"/><path d="M48 27L60 27" stroke="#fff" stroke-width="1.6"/><circle cx="55" cy="11" r="5.5" fill="#e9b98f"/><path d="M49 10Q55 2 61 9Z" fill="#f5b82e"/><path d="M60 22L77 30" stroke="#e9b98f" stroke-width="3.5" stroke-linecap="round"/><path d="M76 28L88 33L84 36" stroke="#223" stroke-width="3" fill="none" stroke-linecap="round"/></symbol>
<symbol id="jet" viewBox="0 0 240 80"><path d="M96 46L156 72L132 72L80 50Z" fill="#c9d3dc"/><path d="M22 36L8 6L26 6L56 34Z" fill="url(#jf)"/><path d="M8 6L16 6L22 14Z" fill="#f5b82e"/><path d="M10 44Q8 36 22 34L190 30Q226 32 238 42Q226 52 190 54L24 54Q10 52 10 44Z" fill="url(#jf)"/><ellipse cx="52" cy="40" rx="22" ry="6" fill="#c5ced6"/><path d="M190 33Q214 34 228 40L196 40Z" fill="#14324d"/><g fill="#14324d"><circle cx="72" cy="42" r="2.2"/><circle cx="86" cy="42" r="2.2"/><circle cx="100" cy="42" r="2.2"/><circle cx="114" cy="42" r="2.2"/><circle cx="128" cy="42" r="2.2"/><circle cx="142" cy="42" r="2.2"/><circle cx="156" cy="42" r="2.2"/><circle cx="170" cy="42" r="2.2"/></g><path d="M14 47L232 45" stroke="#f5b82e" stroke-width="2.4"/></symbol></defs></svg>
<div class="sun"></div><div class="cl" style="top:11%;width:96px;animation-delay:-12s"></div><div class="cl cl2" style="top:24%;width:70px;opacity:.6;animation-delay:-40s"></div><div class="cl cl3" style="top:6%;width:120px;opacity:.5;animation-delay:-62s"></div>
<svg class="wv w1" viewBox="0 0 1200 60" preserveAspectRatio="none"><path d="${WAVE}"/></svg><div class="glint"></div><svg class="wv w2" viewBox="0 0 1200 60" preserveAspectRatio="none"><path d="${WAVE}"/></svg><svg class="wv w3" viewBox="0 0 1200 60" preserveAspectRatio="none"><path d="${WAVE}"/></svg>
${ski('s1')}${ski('s2')}<div class="jsh"></div><div class="jetw"><div class="ct"></div><svg viewBox="0 0 240 80"><use href="#jet" width="240" height="80"/></svg></div><div class="scrim"></div>
${coin('btc c1','₿',58,7,4.2,'left:6%;top:15%')}${coin('usdt c2','₮',52,9,5.4,'right:7%;top:24%')}${coin('btc c3','₿',30,5,3.5,'right:27%;top:7%')}${coin('usdt c4','₮',28,11,6.1,'left:22%;top:68%')}</div>`;
const hdr=()=>`<div class="hero">${SCENE}<img class="logo" src="${LOGO}" alt="IslandPay"></div>`;

// ===== Island Pay application =====
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(m,c='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency:c||'USD'}).format((Number(m)||0)/100);
const dt=d=>d?new Date(d).toLocaleString():'—';
const pill=s=>`<span class="pill ${esc(s)}">${esc(s)}</span>`;
const uuid=()=>crypto.randomUUID?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16));
const parseMinor=v=>{const s=String(v??'').trim().replace(/,/g,'');if(!/^\d{1,9}(\.\d{1,2})?$/.test(s))return null;const[w,f='']=s.split('.');return Number(w)*100+Number((f+'00').slice(0,2))};
const S={user:null,me:null,cfg:null,quote:null,quoteErr:'',amountStr:'',payKey:null,deps:null,receipt:null,authTab:'login',recovery:false,admTab:'summary',adm:{},wdReview:null,destType:'bank'};

async function api(path,opts={}){
  const r=await fetch(path,{method:opts.method||'GET',credentials:'same-origin',headers:{'content-type':'application/json','x-islandpay-request':'1'},body:opts.body?JSON.stringify(opts.body):undefined});
  let d={};try{d=await r.json()}catch{}
  if(!r.ok){const e=new Error(d.error||`Request failed (${r.status})`);e.status=r.status;e.data=d;throw e}
  return d;
}
let tt;function toast(msg,kind=''){const t=$('toast');t.textContent=msg;t.className='toast '+kind;t.hidden=false;clearTimeout(tt);tt=setTimeout(()=>t.hidden=true,4500)}
function busy(f,on){const b=f.querySelector('button[type=submit]');if(!b)return;if(on){b.dataset.t=b.innerHTML;b.disabled=true;b.innerHTML='<span class="spin"></span>Please wait…'}else{b.disabled=false;if(b.dataset.t)b.innerHTML=b.dataset.t}}
const showErr=(f,m)=>{const e=f.querySelector('.err');if(e)e.textContent=m;const o=f.querySelector('.okbox');if(o)o.textContent=''};
const showOk=(f,m)=>{const o=f.querySelector('.okbox');if(o)o.textContent=m;const e=f.querySelector('.err');if(e)e.textContent=''};
function authMsg(e){const m=String(e?.message||e);if(e instanceof ID.MissingIdentityError)return'Login service is not available right now. Please try again shortly.';if(/not confirmed/i.test(m))return'Please confirm your email address first — check your inbox for the verification link.';if(e?.status===401)return'Invalid email or password.';if(e?.status===403)return'Signups are currently closed.';return m}
const isAdmin=()=>Boolean(S.me?.user?.isAdmin);

// ---------- routing ----------
function cur(){const h=decodeURIComponent((location.hash||'#home').slice(1));const[v,...p]=h.split('/');return{v:V[v]?v:'home',p}}
function go(v){if(location.hash==='#'+v)route();else location.hash=v}
function render(){const{v,p}=cur();const wide=v==='admin';$('app').classList.toggle('wide',wide);$('nav').classList.toggle('wide',wide);$('app').innerHTML=V[v](p);
  const tabs=[['home','⌂','Home'],['buy','＋','Buy'],['wallet','◎','Wallet'],['activity','☰','Activity'],['account','👤',S.user?'Account':'Log in']];if(isAdmin())tabs.push(['admin','★','Admin']);
  $('nav').innerHTML=`<a class="brand" href="#home" aria-label="Island Pay home"><img src="${LOGO}" alt="IslandPay"></a>`+tabs.map(t=>`<a class="${t[0]===v?'on':''}" href="#${t[0]}"><i>${t[1]}</i>${t[2]}</a>`).join('');}
async function route(){const{v,p}=cur();render();window.scrollTo(0,0);try{await (L[v]?.(p))}catch(e){if(e.status!==401)toast(e.message,'bad')}render()}
async function loadMe(){if(!S.user){S.me=null;return}try{S.me=await api('/api/me')}catch(e){if(e.status===401){S.me=null}else throw e}}
const needLogin=msg=>`<div class="bal"><b>${msg}</b><p class="mut">Log in or create a free Island Pay account to continue.</p><button class="btn" onclick="A.go('account')">Log in or sign up</button></div>`;

// ---------- views ----------
const depRow=d=>`<div class="row clk" onclick="A.go('receipt/${d.id}')"><div><b>${d.status==='succeeded'?'Credits added':'Deposit'}</b><div class="mut">${dt(d.createdAt)} · ${pill(d.status)}</div></div><div style="text-align:right"><b class="${d.status==='succeeded'?'ok':''}">${d.status==='succeeded'?'+':''}${fmt(d.customerCreditMinor,d.currency)}</b><div class="mut">paid ${fmt(d.grossMinor,d.currency)}</div></div></div>`;
const actList=n=>!S.user?'':S.deps==null?'<div class="card mut" style="text-align:center"><span class="spin dk"></span>Loading…</div>':S.deps.length?`<div class="card">${S.deps.slice(0,n).map(depRow).join('')}</div>`:'<div class="card mut" style="text-align:center">No activity yet. Your deposits and credits will appear here.</div>';
const V={
home:()=>hdr()+(S.user?`<div class="bal"><div class="row" style="border:0;padding:0"><small>Available credits</small><span class="chip s">${esc(S.user.email)}</span></div><div class="n">${S.me?fmt(S.me.balance.availableMinor,S.me.balance.currency):'<span class="spin dk"></span>'}</div><span class="mut">${S.me?esc(S.me.balance.currency)+' credits':''}</span>${S.me?`<div class="row clk" style="margin-top:8px" onclick="A.go('wallet')"><span>IP Coins</span><b>${nc((S.me.balances||[]).find(b=>b.currency==='IPC')?.availableMinor||0)} IPC ›</b></div>`:''}</div>`
  :`<div class="bal"><small>Welcome to Island Pay</small><div class="big">Pay · Shop · Book · Enjoy</div><p class="mut">Buy Island Pay credits securely. A transparent 8.88% platform fee applies — 91.12% of every deposit goes straight to your balance.</p><button class="btn" onclick="A.go('account')">Log in or create account</button></div>`)+
  `<div class="acts"><button class="act" onclick="A.go('buy')"><b>＋</b>Buy credits</button><button class="act" onclick="A.go('activity')"><b>☰</b>Activity</button><button class="act g" onclick="A.go('account')"><b>👤</b>Account</button>${isAdmin()?`<button class="act g" onclick="A.go('admin')"><b>★</b>Admin</button>`:`<button class="act g" onclick="A.go('wallet')"><b>₿</b>Buy crypto</button>`}</div>`+
  (S.user?`<h2>Recent activity</h2>${actList(3)}`:'')+
  `<h2>How it works</h2><div class="card"><div class="row"><span>1. Choose an amount</span><span class="mut">$25 – $10,000</span></div><div class="row"><span>2. Review fee &amp; credits</span><span class="mut">8.88% / 91.12%</span></div><div class="row"><span>3. Pay securely via Banxa</span><span class="mut">Card / bank</span></div><div class="row"><span>4. Credits added</span><span class="mut">after payment is confirmed</span></div></div>`,
buy:()=>{if(!S.user)return hdr()+needLogin('Buy Island Pay credits');const c=S.cfg;const cur$=c?.currency||'USD';
  return hdr()+`<div class="bal"><b>Buy credits</b><label for="amt">Deposit amount (${esc(cur$)})</label><input id="amt" inputmode="decimal" placeholder="0.00" value="${esc(S.amountStr)}" oninput="A.setAmount(this.value)">
  <div class="presets">${(c?.presetsMinor||[2500,5000,10000,25000,50000,100000]).map(m=>`<button type="button" class="${parseMinor(S.amountStr)===m?'on':''}" onclick="A.setAmount('${m/100}',true)">${fmt(m,cur$).replace('.00','')}</button>`).join('')}</div>
  <div class="fee">Island Pay fee: <b>8.88%</b> of each deposit. You receive <b>91.12%</b> as credits. Min ${fmt(c?.minMinor||1000,cur$)}, max ${fmt(c?.maxMinor||1000000,cur$)}.</div></div>
  <div id="rv">${reviewHtml()}</div>${c&&!c.provider.ready?`<div class="note">Online payments are being activated (Banxa merchant approval pending). You can review the fee breakdown now; checkout will open as soon as payments go live. No payment will be taken until then.</div>`:''}`},
activity:()=>hdr()+(S.user?`<div class="bal"><b>All activity</b>${S.deps==null?'<p class="mut"><span class="spin dk"></span>Loading…</p>':S.deps.length?S.deps.map(depRow).join(''):'<p class="mut">No activity yet.</p>'}</div>`:needLogin('Your activity')),
receipt:p=>{if(!S.user)return hdr()+needLogin('Receipt');const r=S.receipt;if(!r||r.deposit.id!==p[0])return hdr()+`<div class="bal"><span class="spin dk"></span>Loading receipt…</div>`;const d=r.deposit;
  const head=d.status==='succeeded'?`<div class="okbox" style="font-size:15px">✓ Payment confirmed — ${fmt(d.customerCreditMinor,d.currency)} credits added to your balance.</div>`
   :['created','pending'].includes(d.status)?`<div class="note" style="margin:10px 0"><span class="spin dk"></span>Waiting for the payment provider to confirm your payment. Credits are added only after confirmation — this page updates automatically.</div>`
   :`<div class="err">${d.status==='review'?'This payment is under review by our team.':esc(d.failureReason||'This payment was not completed.')}</div>`;
  return hdr()+`<div class="bal"><b>Transaction receipt</b>${head}
  <div class="row"><span>Reference</span><span class="mono">${esc(d.id)}</span></div><div class="row"><span>Provider reference</span><span class="mono">${esc(d.providerOrderId||'—')}</span></div>
  <div class="row"><span>Status</span>${pill(d.status)}</div><div class="row"><span>Deposit amount</span><b>${fmt(d.grossMinor,d.currency)}</b></div>
  <div class="row"><span>Island Pay fee (8.88%)</span><span>${fmt(d.companyFeeMinor,d.currency)}</span></div><div class="row"><span>Credits (91.12%)</span><b class="ok">${fmt(d.customerCreditMinor,d.currency)}</b></div>
  <div class="row"><span>Currency</span><span>${esc(d.currency)}</span></div><div class="row"><span>Created</span><span>${dt(d.createdAt)}</span></div><div class="row"><span>Confirmed</span><span>${dt(d.succeededAt)}</span></div>
  ${d.checkoutUrl?`<a class="btn gold noprint" style="display:block;text-align:center;text-decoration:none" href="${esc(d.checkoutUrl)}">Continue to payment</a>`:''}
  <div class="noprint"><button class="btn ghost" onclick="A.refreshReceipt()">Refresh status</button><button class="btn ghost" onclick="print()">Print / save receipt</button></div></div>`},
account:()=>{if(S.recovery)return hdr()+`<div class="bal"><b>Set a new password</b><form onsubmit="A.setPassword(event,true)"><label>New password</label><input name="pw" type="password" minlength="8" required autocomplete="new-password"><label>Confirm password</label><input name="pw2" type="password" minlength="8" required autocomplete="new-password"><div class="err"></div><div class="okbox"></div><button class="btn" type="submit">Save password</button></form></div>`;
  if(!S.user){const t=S.authTab;return hdr()+`<div class="bal"><div class="seg"><button class="${t==='login'?'on':''}" onclick="A.authTab('login')">Log in</button><button class="${t==='signup'?'on':''}" onclick="A.authTab('signup')">Create account</button></div>`+
   (t==='login'?`<form onsubmit="A.login(event)"><label>Email</label><input name="email" type="email" required autocomplete="email"><label>Password</label><input name="password" type="password" required autocomplete="current-password"><div class="err"></div><button class="btn" type="submit">Log in</button></form><button class="linkish" onclick="A.authTab('forgot')">Forgot your password?</button>`
   :t==='signup'?`<form onsubmit="A.signup(event)"><label>Full name</label><input name="name" required maxlength="120" autocomplete="name"><label>Email</label><input name="email" type="email" required autocomplete="email"><label>Password (min. 8 characters)</label><input name="password" type="password" minlength="8" required autocomplete="new-password"><label>Confirm password</label><input name="password2" type="password" minlength="8" required autocomplete="new-password"><label class="chk"><input type="checkbox" name="terms" required> I understand Island Pay charges an 8.88% platform fee on each deposit.</label><div class="err"></div><div class="okbox"></div><button class="btn" type="submit">Create account</button></form>`
   :`<form onsubmit="A.forgot(event)"><p class="mut">Enter your email and we'll send you a link to reset your password.</p><label>Email</label><input name="email" type="email" required autocomplete="email"><div class="err"></div><div class="okbox"></div><button class="btn" type="submit">Send reset link</button></form><button class="linkish" onclick="A.authTab('login')">Back to log in</button>`)+`</div>`}
  const p=S.me?.profile||{};return hdr()+`<div class="bal"><b>IP Coin wallet</b><p class="mut">${nc((S.me?.balances||[]).find(b=>b.currency==='IPC')?.availableMinor||0)} IP Coins</p><div class="two"><button class="btn" onclick="A.go('wallet')">Buy IP Coins</button><button class="btn gold" onclick="A.go('wallet')">BUY CRYPTO</button></div></div><div class="bal"><b>Your account</b><p class="mut">${esc(S.user.email)} · ${S.user.confirmedAt||S.user.emailVerified?'email verified':'email not yet verified'}</p>
  <form onsubmit="A.saveProfile(event)"><label>Full name</label><input name="fullName" maxlength="120" value="${esc(p.fullName||S.user.name||'')}"><div class="two"><div><label>Phone</label><input name="phone" maxlength="40" value="${esc(p.phone||'')}" inputmode="tel"></div><div><label>Country</label><input name="country" maxlength="60" value="${esc(p.country||'')}"></div></div><div class="err"></div><div class="okbox"></div><button class="btn" type="submit">Save details</button></form></div>
  <div class="card" style="margin-top:12px"><b>Change password</b><form onsubmit="A.setPassword(event)"><label>New password</label><input name="pw" type="password" minlength="8" required autocomplete="new-password"><label>Confirm password</label><input name="pw2" type="password" minlength="8" required autocomplete="new-password"><div class="err"></div><div class="okbox"></div><button class="btn ghost" type="submit">Update password</button></form></div>
  <div class="pad"><button class="btn bad" onclick="A.logout()">Log out</button></div>`},
admin:()=>{if(!S.user)return hdr()+needLogin('Administrator');if(!S.me)return hdr()+'<div class="bal"><span class="spin dk"></span>Loading…</div>';if(!isAdmin())return hdr()+'<div class="bal"><b>Administrator access required</b><p class="mut">This area is restricted to authorized Island Pay administrators.</p></div>';
  const T=[['summary','Revenue'],['withdrawals','Withdrawals'],['destinations','Payout destinations'],['deposits','Deposits'],['coins','IP Coins'],['redemptions','Crypto queue'],['reserves','Reserves'],['customers','Customers'],['ledger','Ledger'],['audit','Audit log'],['emails','Emails']];
  return hdr()+`<div class="bal"><b>Island Pay administration</b><p class="mut">All figures come from the live ledger database.</p></div><div class="tabs">${T.map(t=>`<button class="${S.admTab===t[0]?'on':''}" onclick="A.admTab('${t[0]}')">${t[1]}</button>`).join('')}</div>${ADM[S.admTab]()}`}
};
function reviewHtml(){const q=S.quote;if(S.quoteErr)return`<div class="card"><div class="err" style="margin:0">${esc(S.quoteErr)}</div></div>`;if(!q)return'';
  return`<div class="card"><b>Review your purchase</b><div class="row"><span>Deposit amount</span><b>${fmt(q.grossMinor,q.currency)}</b></div><div class="row"><span>Island Pay fee (8.88%)</span><span>− ${fmt(q.companyFeeMinor,q.currency)}</span></div><div class="row"><span>Credits you receive (91.12%)</span><b class="ok" style="font-size:18px">${fmt(q.customerCreditMinor,q.currency)}</b></div><div class="row"><span>Currency</span><span>${esc(q.currency)}</span></div><div class="row"><span><b>Total payment</b></span><b>${fmt(q.totalPaymentMinor,q.currency)}</b></div>
  <p class="fee">The payment provider may show its own processing or network fee at checkout. Credits are added only after the payment is confirmed by the provider.</p>
  <label class="chk"><input type="checkbox" id="feeok"> I understand the 8.88% Island Pay fee and that I will receive ${fmt(q.customerCreditMinor,q.currency)} in credits.</label><div class="err" id="payerr"></div>
  <button class="btn gold" id="paybtn" onclick="A.pay()">Continue to secure payment</button></div>`}

// ---------- admin panels ----------
const tile=(k,v)=>`<div class="tile"><small>${k}</small><div>${v}</div></div>`;
const tbl=(h,rows)=>`<div class="card scroll"><table class="tbl"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${h.length}" class="mut">No records yet.</td></tr>`}</tbody></table></div>`;
const loading='<div class="card mut"><span class="spin dk"></span>Loading…</div>';
const ADM={
summary:()=>{const s=S.adm.summary;if(!s)return loading;const c=s.currency,r=s.revenue,w=s.withdrawals,R=s.reconciliation,I=s.integrations,yn=b=>pill(b?'yes':'no');
  return`<div class="grid">${tile('Total revenue earned',fmt(r.totalEarnedMinor,c))+tile('Available company balance',fmt(r.availableMinor,c))+tile('Reserved for withdrawals',fmt(r.reservedForWithdrawalsMinor,c))+tile('Total withdrawn',fmt(r.totalWithdrawnMinor,c))+tile('Pending withdrawals',fmt(w.pendingMinor,c))+tile('Bank withdrawals (paid)',fmt(w.paidBankMinor,c))+tile('Crypto withdrawals (paid)',fmt(w.paidCryptoMinor,c))+tile(`Failed withdrawals (${w.failedCount})`,fmt(w.failedMinor,c))+tile('Provider transaction fees',fmt(r.providerFeesMinor,c))+tile('Refunds & reversals',fmt(r.refundsReversalsMinor,c))+tile('Withdrawal fees',fmt(r.withdrawalFeesMinor,c))+tile('Net revenue',fmt(r.netRevenueMinor,c))+tile('Customer credits outstanding',fmt(s.customers.totalCreditsOutstandingMinor,c))}</div>
  <div class="card"><b>Deposits by status</b>${Object.entries(s.deposits).map(([k,v])=>`<div class="row"><span>${pill(k)} × ${v.count}</span><b>${fmt(v.grossMinor,c)}</b></div>`).join('')||'<p class="mut">No deposits yet.</p>'}</div>
  <div class="card"><b>Ledger reconciliation</b><div class="row"><span>Company revenue matches ledger</span>${yn(R.companyRevenueMatchesLedger)}</div><div class="row"><span>Company balances match ledger</span>${yn(R.companyBalancesMatchLedger)}</div><div class="row"><span>Customer balances match ledger</span>${yn(R.customerTotalMatchesLedger)}</div><div class="row"><span>Customers with mismatches</span><b>${R.customersWithMismatch}</b></div></div>
  <div class="card"><b>Integrations</b><div class="row"><span>Banxa checkout (${esc(I.banxaEnvironment)})</span>${yn(I.banxaCheckout)}</div><div class="row"><span>Banxa webhook</span>${yn(I.banxaWebhook)}</div><div class="row"><span>Webhook URL</span><span class="mono">${esc(location.origin+I.webhookPath)}</span></div><div class="row"><span>Resend email</span>${yn(I.email)}</div><div class="row"><span>Admin alert email</span>${yn(I.adminEmailConfigured)}</div></div>
  <div class="note">The company balance is an internal ledger figure. Funds are never sent automatically — use Withdrawals to request a payout.</div>`},
withdrawals:()=>{const d=S.adm.destinations,w=S.adm.withdrawals;if(!d||!w)return loading;const c=S.adm.summary?.currency||'USD';const ok=d.filter(x=>x.verifiedAt&&!x.disabled);const rv=S.wdReview;
  const form=rv?`<div class="card"><b>Review withdrawal</b><div class="row"><span>Amount</span><b>${fmt(rv.amountMinor,c)}</b></div><div class="row"><span>Fee</span><span>${fmt(rv.feeMinor,c)}</span></div><div class="row"><span>Total deducted from company balance</span><b>${fmt(rv.amountMinor+rv.feeMinor,c)}</b></div><div class="row"><span>Method</span><span>${esc(rv.dest.type)}</span></div>${destDetail(rv.dest)}
    <label class="chk"><input type="checkbox" id="wdok"> I have verified the destination details above are the correct company ${rv.dest.type==='crypto'?'wallet, asset and network':'bank account'}.</label><div class="err" id="wderr"></div><button class="btn gold" onclick="A.wdConfirm()">Confirm withdrawal request</button><button class="btn ghost" onclick="A.wdCancel()">Back</button></div>`
   :`<div class="card"><b>New company withdrawal</b><p class="mut">Available: <b>${fmt(S.adm.summary?.revenue.availableMinor,c)}</b>. A request reserves funds; it is not a payment until settlement is confirmed.</p>${ok.length?`<form onsubmit="A.wdReview(event)"><label>Destination</label><select name="dest">${ok.map(x=>`<option value="${x.id}">${x.type==='crypto'?'Crypto':'Bank'} · ${esc(x.label)}</option>`).join('')}</select><div class="two"><div><label>Amount (${c})</label><input name="amount" inputmode="decimal" required placeholder="0.00"></div><div><label>Applicable fee (${c})</label><input name="fee" inputmode="decimal" value="0.00"></div></div><div class="err"></div><button class="btn" type="submit">Review withdrawal</button></form>`:'<p class="err">Add and verify a payout destination first.</p>'}</div>`;
  const act=(x,a,l,cls='ghost')=>`<button class="btn sm ${cls}" onclick="A.wdAct('${x.id}','${a}')">${l}</button>`;
  return form+tbl(['Created','Amount','Fee','Destination','Status','Reference','Actions'],w.map(x=>`<tr><td>${dt(x.createdAt)}<div class="mut">${esc(x.requestedByEmail||'')}</div></td><td><b>${fmt(x.amountMinor,x.currency)}</b></td><td>${fmt(x.feeMinor,x.currency)}</td><td class="mono">${esc(x.destination)}</td><td>${pill(x.status)}${x.failureReason?`<div class="mut">${esc(x.failureReason)}</div>`:''}</td><td class="mono">${esc(x.providerReference||'—')}</td><td>${x.status==='requested'?act(x,'approve','Approve','')+act(x,'reject','Reject','bad'):''}${x.status==='approved'?act(x,'processing','Mark processing')+act(x,'paid','Confirm settled','')+act(x,'failed','Failed','bad'):''}${x.status==='processing'?act(x,'paid','Confirm settled','')+act(x,'failed','Failed','bad'):''}</td></tr>`))},
destinations:()=>{const d=S.adm.destinations;if(!d)return loading;const t=S.destType;
  return`<div class="card"><b>Add company payout destination</b><div class="seg" style="margin-top:8px"><button class="${t==='bank'?'on':''}" onclick="A.destType('bank')">Bank account</button><button class="${t==='crypto'?'on':''}" onclick="A.destType('crypto')">Crypto wallet</button></div><form onsubmit="A.destAdd(event)"><label>Label</label><input name="label" required maxlength="80" placeholder="${t==='bank'?'Company operating account':'Company treasury wallet'}">`+
   (t==='bank'?`<label>Beneficiary (company) name</label><input name="beneficiaryName" required><div class="two"><div><label>Bank name</label><input name="bankName" required></div><div><label>SWIFT / BIC</label><input name="swift" maxlength="11"></div></div><label>Account number / IBAN</label><input name="accountNumber" required>`
   :`<div class="two"><div><label>Asset</label><select name="asset"><option>USDT</option><option>BTC</option><option>USDC</option></select></div><div><label>Network</label><select name="network"><option>TRC20</option><option>ERC20</option><option>BEP20</option><option>Solana</option><option>Polygon</option><option>Arbitrum</option><option>Bitcoin</option></select></div></div><label>Wallet address</label><input name="address" required class="mono">`)+
   `<div class="err"></div><button class="btn" type="submit">Save destination</button></form><p class="fee">New destinations must be verified (by re-entering the last 6 characters) before they can receive withdrawals.</p></div>`+
   tbl(['Destination','Details','Verified','Actions'],d.map(x=>`<tr><td><b>${esc(x.label)}</b><div class="mut">${esc(x.type)}${x.disabled?' · disabled':''}</div></td><td>${destDetail(x,true)}</td><td>${x.verifiedAt?pill('yes')+`<div class="mut">${esc(x.verifiedBy)}</div>`:pill('no')}</td><td>${!x.verifiedAt&&!x.disabled?`<button class="btn sm" onclick="A.destVerify('${x.id}')">Verify</button>`:''}${!x.disabled?`<button class="btn sm bad" onclick="A.destDisable('${x.id}')">Disable</button>`:''}</td></tr>`))},
deposits:()=>{const d=S.adm.deposits;if(!d)return loading;return tbl(['Created','Customer','Gross','Fee 8.88%','Credits','Provider fee','Status','Provider ref','Actions'],d.map(x=>`<tr><td>${dt(x.createdAt)}</td><td>${esc(x.email)}</td><td><b>${fmt(x.grossMinor,x.currency)}</b></td><td>${fmt(x.companyFeeMinor,x.currency)}</td><td>${fmt(x.customerCreditMinor,x.currency)}</td><td>${fmt(x.providerFeeMinor,x.currency)}</td><td>${pill(x.status)}<div class="mut">${esc(x.providerStatus||'')} · ${esc(x.settlementStatus)}</div></td><td class="mono">${esc(x.providerOrderId||'—')}</td><td><a class="btn sm ghost" href="#receipt/${x.id}">Receipt</a>${x.providerOrderId&&!['succeeded','refunded','reversed'].includes(x.status)?`<button class="btn sm ghost" onclick="A.depRefresh('${x.id}')">Check provider</button>`:''}${x.status==='succeeded'?`<button class="btn sm bad" onclick="A.depReverse('${x.id}')">Refund / reverse</button>`:''}</td></tr>`))},
ledger:()=>{const e=S.adm.ledger;if(!e)return loading;return tbl(['#','Date','Account','Direction','Kind','Amount','Memo','Ref'],e.map(x=>`<tr><td>${x.id}</td><td>${dt(x.createdAt)}</td><td>${esc(x.account)}</td><td>${esc(x.direction)}</td><td>${esc(x.kind)}</td><td><b>${x.direction==='debit'?'−':'+'}${fmt(x.amountMinor,x.currency)}</b></td><td>${esc(x.memo)}</td><td class="mono">${esc(x.depositId||x.withdrawalId||'')}</td></tr>`))},
audit:()=>{const e=S.adm.audit;if(!e)return loading;return tbl(['Date','Actor','Action','Entity','Details'],e.map(x=>`<tr><td>${dt(x.createdAt)}</td><td>${esc(x.actorEmail||'system')}</td><td><b>${esc(x.action)}</b></td><td class="mono">${esc((x.entityType||'')+' '+(x.entityId||''))}</td><td class="mono">${esc(x.details?JSON.stringify(x.details).slice(0,240):'')}</td></tr>`))},
emails:()=>{const e=S.adm.emails;if(!e)return loading;return tbl(['Date','Recipient','Template','Status','Error'],e.map(x=>`<tr><td>${dt(x.createdAt)}</td><td>${esc(x.recipient)}</td><td>${esc(x.template)}</td><td>${pill(x.status)}</td><td class="mut">${esc(x.error||'')}</td></tr>`))},
};
const destDetail=(d,short)=>d.type==='crypto'?`<div class="row"><span>Asset / network</span><b>${esc(d.asset)} · ${esc(d.network)}</b></div><div class="row"><span>Wallet address</span><span class="mono">${esc(d.address)}</span></div>`
  :`<div class="row"><span>Beneficiary</span><b>${esc(d.beneficiaryName)}</b></div><div class="row"><span>Bank</span><span>${esc(d.bankName)}${d.swift?' · '+esc(d.swift):''}</span></div><div class="row"><span>Account / IBAN</span><span class="mono">${esc(short?'••••'+String(d.accountNumber||'').slice(-4):d.accountNumber)}</span></div>`;

// ---------- loaders ----------
const L={
home:async()=>{if(S.user){await loadMe();S.deps=(await api('/api/deposits')).deposits}},
activity:async()=>{if(S.user)S.deps=(await api('/api/deposits')).deposits},
buy:async()=>{S.cfg=await api('/api/quote')},
account:async()=>{if(S.user)await loadMe()},
receipt:async p=>{if(!S.user||!p[0])return;S.receipt=await api('/api/deposits/'+encodeURIComponent(p[0]));pollReceipt(p[0])},
admin:async()=>{if(!S.me)await loadMe();if(isAdmin())await loadAdm()},
};
async function loadAdm(){const t=S.admTab;const need={summary:['summary'],withdrawals:['summary','destinations','withdrawals'],destinations:['destinations'],deposits:['deposits'],ledger:['ledger'],audit:['audit'],emails:['emails'],coins:['coins'],redemptions:['redemptions'],reserves:['reserves'],customers:[]}[t];
  await Promise.all(need.map(async k=>{const d=await api('/api/admin/'+k);S.adm[k]=k==='summary'||k==='coins'||k==='reserves'?d:(d[k]||d.entries)}))}
let pollN=0,pollId=null;
async function pollReceipt(id){if(pollId===id)return;pollId=id;pollN=0;
  const tick=async()=>{if(cur().v!=='receipt'||cur().p[0]!==id){pollId=null;return}const d=S.receipt?.deposit;if(!d||!['created','pending'].includes(d.status)||pollN++>20){pollId=null;return}
    try{const r=await api(`/api/deposits/${id}/refresh`,{method:'POST'});S.receipt.deposit=r.deposit;if(r.deposit.status==='succeeded'){toast('Payment confirmed — credits added!','ok');loadMe()}render()}catch{}setTimeout(tick,6000)};
  setTimeout(tick,1500)}

// ---------- actions ----------
let qT;
const A=window.A={go,
 setAmount(v,now){S.amountStr=v;S.payKey=null;S.quote=null;S.quoteErr='';if(now)render();clearTimeout(qT);const m=parseMinor(v);if(!v){$('rv')&&($('rv').innerHTML='');return}
  if(m==null){S.quoteErr='Enter a valid amount with up to 2 decimals.';$('rv').innerHTML=reviewHtml();return}
  qT=setTimeout(async()=>{if($('rv'))$('rv').innerHTML='<div class="card mut"><span class="spin dk"></span>Calculating…</div>';try{S.quote=await api('/api/quote?amount='+encodeURIComponent((m/100).toFixed(2)))}catch(e){S.quoteErr=e.message}if(parseMinor(S.amountStr)===m&&$('rv'))$('rv').innerHTML=reviewHtml()},now?0:350)},
 async pay(){const b=$('paybtn'),er=$('payerr');er.textContent='';if(!$('feeok').checked){er.textContent='Please confirm the 8.88% Island Pay fee to continue.';return}
  S.payKey=S.payKey||uuid();b.disabled=true;b.innerHTML='<span class="spin"></span>Starting secure checkout…';
  try{const r=await api('/api/deposits',{method:'POST',body:{amountMinor:S.quote.grossMinor,idempotencyKey:S.payKey,acceptFee:true}});location.href=r.checkoutUrl}
  catch(e){er.textContent=e.message;b.disabled=false;b.innerHTML='Continue to secure payment';if(e.status!==409)S.payKey=null}},
 async refreshReceipt(){const id=S.receipt?.deposit.id;if(!id)return;try{const r=await api(`/api/deposits/${id}/refresh`,{method:'POST'});S.receipt.deposit=r.deposit;render();toast('Status updated')}catch(e){toast(e.message,'bad')}},
 authTab(t){S.authTab=t;render()},
 async login(e){e.preventDefault();const f=e.target;busy(f,true);try{await ID.login(f.email.value.trim(),f.password.value);S.user=await ID.getUser();await loadMe();toast('Welcome back to Island Pay','ok');go('home')}catch(err){showErr(f,authMsg(err))}finally{busy(f,false)}},
 async signup(e){e.preventDefault();const f=e.target;if(f.password.value!==f.password2.value)return showErr(f,'Passwords do not match.');busy(f,true);
  try{const u=await ID.signup(f.email.value.trim(),f.password.value,{full_name:f.name.value.trim()});if(u?.emailVerified){S.user=await ID.getUser();await loadMe();toast('Account created','ok');go('home')}else{f.reset();showOk(f,'Account created! Check your email and click the verification link to activate your account, then log in.')}}
  catch(err){showErr(f,authMsg(err))}finally{busy(f,false)}},
 async forgot(e){e.preventDefault();const f=e.target;busy(f,true);try{await ID.requestPasswordRecovery(f.email.value.trim());showOk(f,'If an account exists for that email, a password reset link is on its way.')}catch(err){showErr(f,authMsg(err))}finally{busy(f,false)}},
 async setPassword(e,recovery){e.preventDefault();const f=e.target;if(f.pw.value!==f.pw2.value)return showErr(f,'Passwords do not match.');busy(f,true);try{await ID.updateUser({password:f.pw.value});f.reset();if(recovery){S.recovery=false;S.user=await ID.getUser();await loadMe();toast('Password updated','ok');go('home')}else showOk(f,'Password updated.')}catch(err){showErr(f,authMsg(err))}finally{busy(f,false)}},
 async saveProfile(e){e.preventDefault();const f=e.target;busy(f,true);try{S.me=await api('/api/me',{method:'PATCH',body:{fullName:f.fullName.value,phone:f.phone.value,country:f.country.value}});showOk(f,'Details saved.')}catch(err){showErr(f,err.message)}finally{busy(f,false)}},
 async logout(){try{await ID.logout()}catch{}Object.assign(S,{user:null,me:null,deps:null,receipt:null,adm:{}});toast('You have been logged out');go('home')},
 async admTab(t){S.admTab=t;S.wdReview=null;render();try{await loadAdm()}catch(e){toast(e.message,'bad')}render()},
 destType(t){S.destType=t;render()},
 async destAdd(e){e.preventDefault();const f=e.target;const body={type:S.destType};for(const el of f.elements)if(el.name)body[el.name]=el.value;busy(f,true);try{await api('/api/admin/destinations',{method:'POST',body});toast('Destination saved — verify it next','ok');await loadAdm();render()}catch(err){showErr(f,err.message)}finally{busy(f,false)}},
 async destVerify(id){const v=prompt('Destination verification: re-enter the LAST 6 characters of the account number / wallet address from your official company records.');if(!v)return;try{await api(`/api/admin/destinations/${id}/verify`,{method:'POST',body:{confirmLast6:v}});toast('Destination verified','ok');await loadAdm();render()}catch(e){toast(e.message,'bad')}},
 async destDisable(id){if(!confirm('Disable this payout destination?'))return;try{await api(`/api/admin/destinations/${id}/disable`,{method:'POST'});await loadAdm();render()}catch(e){toast(e.message,'bad')}},
 wdReview(e){e.preventDefault();const f=e.target;const a=parseMinor(f.amount.value),fee=parseMinor(f.fee.value||'0');if(!a)return showErr(f,'Enter a valid amount.');if(fee==null)return showErr(f,'Enter a valid fee.');
  const dest=S.adm.destinations.find(x=>x.id===f.dest.value);S.wdReview={amountMinor:a,feeMinor:fee,dest,key:uuid()};render()},
 wdCancel(){S.wdReview=null;render()},
 async wdConfirm(){const rv=S.wdReview;if(!$('wdok').checked){$('wderr').textContent='Please confirm you verified the destination.';return}
  try{await api('/api/admin/withdrawals',{method:'POST',body:{amountMinor:rv.amountMinor,feeMinor:rv.feeMinor,destinationId:rv.dest.id,idempotencyKey:rv.key,confirmDestination:true}});S.wdReview=null;toast('Withdrawal requested — funds reserved','ok');await loadAdm();render()}catch(e){$('wderr').textContent=e.message}},
 async wdAct(id,action){const body={};if(action==='paid'){const r=prompt('Enter the bank transfer reference or blockchain transaction hash confirming settlement:');if(!r)return;body.providerReference=r}
  if(action==='failed'||action==='reject'){const r=prompt('Reason:');if(!r)return;body.reason=r}if(!body.providerReference&&!body.reason&&!confirm(`Mark withdrawal as ${action}?`))return;
  try{await api(`/api/admin/withdrawals/${id}/${action}`,{method:'POST',body});toast('Withdrawal updated','ok');await loadAdm();render()}catch(e){toast(e.message,'bad')}},
 async depRefresh(id){try{const r=await api(`/api/admin/deposits/${id}/refresh`,{method:'POST'});toast('Provider result: '+r.result);await loadAdm();render()}catch(e){toast(e.message,'bad')}},
 async depReverse(id){const reason=prompt('Reason for refund / reversal (e.g. chargeback reference):');if(!reason)return;const refunded=confirm('Press OK if this is a REFUND, or Cancel for a REVERSAL / chargeback.');if(!confirm('This removes the customer credits and the 8.88% company revenue for this deposit and records reversal entries. Continue?'))return;
  try{await api(`/api/admin/deposits/${id}/reverse`,{method:'POST',body:{reason,kind:refunded?'refunded':'reversed',confirm:true}});toast('Reversal recorded','ok');await loadAdm();render()}catch(e){toast(e.message,'bad')}},
};

// ---------- IP Coin wallet & crypto shop ----------
const nc=n=>new Intl.NumberFormat('en-US').format(Number(n)||0);
const W={w:null,pkg:null,payKey:null,asset:'USDT',network:'TRC20',coins:'',addr:'',q:null,qErr:'',redKey:null};
const redRow=r=>`<div class="row"><div><b>${esc(r.cryptoAmount)} ${esc(r.asset)}</b> <span class="mut">${esc(r.network)}</span><div class="mut">${esc(r.reference)} · ${dt(r.createdAt)} · ${pill(r.status)}</div><div class="mono mut">${esc(r.walletAddress)}</div>${r.txHash?`<div class="mono">tx ${esc(r.txHash)}</div>`:''}${r.failureReason?`<div class="mut">${esc(r.failureReason)}</div>`:''}</div><b>−${nc(r.coins)} IPC</b></div>`;
const ordRow=o=>`<div class="row"><div><b>${nc(o.coins)} IP Coins</b>${o.testMode?' <span class="chip s">TEST</span>':''}<div class="mut">${dt(o.createdAt)} · ${pill(o.status)}${o.failureReason?' · '+esc(o.failureReason):''}</div></div><b class="${o.status==='paid'?'ok':''}">${fmt(o.amountMinor)}</b></div>`;
function quoteHtml(){if(W.qErr)return`<div class="err">${esc(W.qErr)}</div>`;const q=W.q;if(!q)return'';const left=Math.max(0,Math.round((new Date(q.expiresAt)-Date.now())/1000));
  return`<div class="card"><b>Review your crypto purchase</b><div class="row"><span>Pay with</span><b>${nc(q.coins)} IP Coins (${fmt(q.usdMinor)})</b></div><div class="row"><span>Live rate (${esc(q.rateSource)})</span><span>1 ${esc(q.asset)} = $${Number(q.rateUsd).toLocaleString('en-US',{maximumFractionDigits:4})}</span></div>
  <div class="row"><span>Service fee</span><span>− ${fmt(q.serviceFeeMinor)}</span></div><div class="row"><span>Network fee (${esc(q.network)})</span><span>− ${fmt(q.networkFeeMinor)}</span></div>
  <div class="row"><span>You receive</span><b class="ok" style="font-size:18px">${esc(q.cryptoAmount)} ${esc(q.asset)}</b></div><div class="row"><span>To wallet</span><span class="mono">${esc(W.addr)}</span></div>
  <p class="fee">Quote valid ${left>0?`for ${left}s`:'— expired, get a new quote'}. Crypto transfers are irreversible: check that the address is yours and on the <b>${esc(q.network)}</b> network. Island Pay will never ask for your private key or seed phrase.</p>
  <label class="chk"><input type="checkbox" id="redok"> I confirm the wallet address and network are correct and I own this wallet.</label><div class="err" id="rederr"></div>
  <button class="btn gold" id="redbtn" onclick="A.redeem()" ${left>0?'':'disabled'}>Confirm purchase</button></div>`}
V.wallet=()=>{if(!S.user)return hdr()+needLogin('IP Coin wallet');const w=W.w;if(!w)return hdr()+'<div class="bal"><span class="spin dk"></span>Loading wallet…</div>';const cr=w.crypto;const nets=cr.networks[W.asset]||[];
  return hdr()+`<div class="bal"><small>IP Coin balance</small><div class="n">${nc(w.coins)} <span style="font-size:.5em">IPC</span></div><span class="mut">≈ ${fmt(w.coins*10)} · $1 = 10 IP Coins</span></div>
  <h2>Buy IP Coins</h2><div class="card"><div class="presets">${w.packages.map(p=>`<button type="button" class="${W.pkg===p.id?'on':''}" onclick="A.pickPkg('${p.id}')">${fmt(p.amountMinor).replace('.00','')}<br><small>${nc(p.coins)} coins</small></button>`).join('')}</div>
  ${w.card.ready?`${w.card.testMode?'<div class="note">TEST MODE — CX Pay test transactions only. No real card will be charged.</div>':''}<div class="err" id="pkgerr"></div><button class="btn gold" onclick="A.buyCoins()" ${W.pkg?'':'disabled'}>Pay by card (Visa · Mastercard · Amex)</button>`
   :'<div class="note">Card payments via CX Pay / Aruba Bank are awaiting merchant approval. No payment can be taken yet.</div>'}
  <div class="note">Local bank payment (Sentoo) — coming soon, pending merchant agreement.</div><p class="fee">Coins are added only after the card processor approves the payment.</p></div>
  <h2>Buy crypto</h2>${cr.mode==='off'?'<div class="card mut">The crypto shop is currently unavailable.</div>':`<div class="card">${cr.mode==='test'?'<div class="note">TEST MODE — orders are queued for manual review; no crypto is sent automatically.</div>':''}
  <div class="seg">${['USDT','BTC'].map(a=>`<button class="${W.asset===a?'on':''}" onclick="A.cAsset('${a}')">${a==='USDT'?'₮ USDT':'₿ Bitcoin'}</button>`).join('')}</div>
  <label>Network</label><select onchange="A.cSet('network',this.value)">${nets.map(n=>`<option value="${n.id}" ${W.network===n.id?'selected':''}>${esc(n.label)}</option>`).join('')}</select>
  <label>IP Coins to spend (${nc(cr.minCoins)} – ${nc(cr.maxCoins)})</label><input inputmode="numeric" value="${esc(W.coins)}" oninput="A.cSet('coins',this.value)" placeholder="e.g. 500">
  <label>Your ${esc(W.asset)} wallet address (${esc(W.network)})</label><input class="mono" value="${esc(W.addr)}" oninput="A.cSet('addr',this.value)" autocomplete="off" spellcheck="false" placeholder="${W.network==='BTC'?'bc1…':W.network==='TRC20'?'T…':'0x…'}">
  <p class="fee">Service fee ${(cr.serviceFeeBps/100).toFixed(2)}% + network fee ${fmt(cr.networkFeeMinor[W.network]||0)}. Enter only your public address — never a private key or seed phrase.</p>
  <button class="btn" onclick="A.getQuote()">Review live price</button></div><div id="qv">${quoteHtml()}</div>`}
  <h2>Crypto purchases</h2><div class="card">${w.redemptions.length?w.redemptions.map(redRow).join(''):'<p class="mut">No crypto purchases yet.</p>'}</div>
  <h2>Coin purchases</h2><div class="card">${w.orders.length?w.orders.map(ordRow).join(''):'<p class="mut">No coin purchases yet.</p>'}</div>`};
L.wallet=async()=>{if(S.user)W.w=await api('/api/wallet')};
let cjsLoaded=null;
function loadCollect(w){if(cjsLoaded)return cjsLoaded;cjsLoaded=new Promise((res,rej)=>{const s=document.createElement('script');s.src=w.card.collectJsUrl;s.setAttribute('data-tokenization-key',w.card.tokenizationKey);s.setAttribute('data-variant','lightbox');s.onload=()=>res(window.CollectJS);s.onerror=()=>{cjsLoaded=null;rej(new Error('Could not load the secure card form.'))};document.head.appendChild(s)});return cjsLoaded}
Object.assign(A,{
 pickPkg(id){W.pkg=id;W.payKey=null;render()},
 async buyCoins(){const er=$('pkgerr');er.textContent='';try{const CJ=await loadCollect(W.w);W.payKey=W.payKey||uuid();
   CJ.configure({variant:'lightbox',callback:async r=>{try{const o=await api('/api/wallet/purchase',{method:'POST',body:{packageId:W.pkg,paymentToken:r.token,idempotencyKey:W.payKey}});W.payKey=null;W.pkg=null;toast(`Payment approved — ${nc(o.order.coins)} IP Coins added`,'ok');await L.wallet();render()}catch(e){toast(e.message,'bad');if(e.status!==409)W.payKey=null;await L.wallet().catch(()=>{});render()}}});
   CJ.startPaymentRequest()}catch(e){er.textContent=e.message}},
 cAsset(a){W.asset=a;W.network=W.w.crypto.networks[a][0].id;W.q=null;W.qErr='';render()},
 cSet(k,v){W[k]=v.trim?v.trim():v;W.q=null;W.qErr='';if(k==='network')render();else if($('qv'))$('qv').innerHTML=''},
 async getQuote(){W.qErr='';W.q=null;if(!W.addr){W.qErr='Enter your wallet address.';render();return}
  try{W.q=(await api('/api/wallet/quote',{method:'POST',body:{asset:W.asset,network:W.network,coins:Number(W.coins)}})).quote;W.redKey=uuid()}catch(e){W.qErr=e.message}render();
  clearInterval(W.t);W.t=setInterval(()=>{if(cur().v!=='wallet'||!W.q){clearInterval(W.t);return}const ok=$('redok')?.checked;if($('qv'))$('qv').innerHTML=quoteHtml();if(ok&&$('redok'))$('redok').checked=true},1000)},
 async redeem(){const er=$('rederr');er.textContent='';if(!$('redok').checked){er.textContent='Please confirm the wallet address and network.';return}const b=$('redbtn');b.disabled=true;b.innerHTML='<span class="spin"></span>Placing order…';
  try{const r=await api('/api/wallet/redeem',{method:'POST',body:{quoteId:W.q.id,walletAddress:W.addr,idempotencyKey:W.redKey,confirm:true}});clearInterval(W.t);W.q=null;W.coins='';toast(`Order ${r.redemption.reference} placed — coins reserved, delivery pending`,'ok');await L.wallet();await loadMe();render()}
  catch(e){er.textContent=e.message;b.disabled=false;b.innerHTML='Confirm purchase'}},
});
// ---------- admin: IP Coin & crypto ----------
const cs=(k,v)=>tile(k,v);
Object.assign(ADM,{
coins:()=>{const s=S.adm.coins;if(!s)return loading;const C=s.coins,L2=s.cash.live,T=s.cash.test,K=s.crypto,yn=b=>pill(b?'yes':'no');
  return`<h2>Customer liabilities (IP Coins)</h2><div class="grid">${cs('Total IP Coins issued',nc(C.issued))+cs('Coins spent on crypto',nc(C.spent))+cs('Returned (failed/refunded)',nc(C.returnedFromFailed))+cs('Reversed by card refunds',nc(C.reversedByRefunds))+cs('Outstanding customer balances',nc(C.outstanding)+' IPC')+cs('Outstanding liability (USD)',fmt(C.outstandingUsdLiabilityMinor))}</div>
  <h2>Business cash (card &amp; bank — live)</h2><div class="grid">${cs('Card payments',fmt(L2.cardMinor))+cs('Bank payments',fmt(L2.bankMinor))+cs('Processing fees (est.)',fmt(L2.processingFeesMinor))+cs('Refunds',fmt(L2.refundsMinor))+cs('Net settlement',fmt(L2.netSettlementMinor))+cs('Crypto service fees earned',fmt(K.serviceFeesEarnedMinor))}</div>
  <div class="note">Test-mode payments (excluded above): ${fmt(T.grossMinor)} gross · ${s.cash.failedOrders} failed orders · ${s.cash.reviewOrders} orders in review.</div>
  <h2>Crypto reserves &amp; deliveries</h2><div class="grid">${K.reserves.map(r=>cs(`${r.asset} reserve (${r.network})`,r.balance)).join('')||cs('Reserves','none recorded')}${cs('USDT purchased',K.purchased.USDT)+cs('USDT delivered',K.delivered.USDT)+cs('BTC purchased',K.purchased.BTC)+cs('BTC delivered',K.delivered.BTC)+cs('Pending redemptions',K.pendingCount+` (owed ${K.owedPending.USDT} USDT · ${K.owedPending.BTC} BTC)`)+cs('Failed / refunded',K.failedCount+' / '+K.refundedCount)}</div>
  <div class="card"><b>Status</b><div class="row"><span>Coin balances match ledger</span>${yn(C.ledgerMatches)}</div><div class="row"><span>CX Pay card checkout (${esc(s.config.cardMode)})</span>${yn(s.config.cardReady)}</div><div class="row"><span>CX Pay webhook</span>${yn(s.config.cardWebhook)}</div><div class="row"><span>Webhook URL</span><span class="mono">${esc(location.origin)}/api/webhooks/cxpay</span></div><div class="row"><span>Sentoo bank payments</span>${yn(s.config.bankReady)}</div><div class="row"><span>Crypto shop mode</span><b>${esc(s.config.cryptoMode)}</b></div><div class="row"><span>Fulfillment</span><b>${esc(s.config.fulfillment)}</b></div></div>
  <div class="note">Customer coin liabilities, business cash and actual crypto reserves are tracked separately. Reserves only change when you record verified funding or a verified delivery.</div>`},
redemptions:()=>{const d=S.adm.redemptions;if(!d)return loading;const b=(x,a,l,c='ghost')=>`<button class="btn sm ${c}" onclick="A.redAct('${x.id}','${a}')">${l}</button>`;
  return tbl(['Created','Ref / customer','Deliver','Wallet','Coins','Status','Tx / verification','Actions'],d.map(x=>`<tr><td>${dt(x.createdAt)}</td><td><b>${esc(x.reference)}</b><div class="mut">${esc(x.email)}</div></td><td><b>${esc(x.cryptoAmount)} ${esc(x.asset)}</b><div class="mut">${esc(x.network)} @ $${esc(x.rateUsd)}</div></td><td class="mono">${esc(x.walletAddress)}</td><td>${nc(x.coins)}</td><td>${pill(x.status)}${x.failureReason?`<div class="mut">${esc(x.failureReason)}</div>`:''}</td><td class="mono">${esc(x.txHash||'')}<div class="mut">${esc(x.verification||'')}</div></td><td>${['pending','processing'].includes(x.status)?(x.status==='pending'?b(x,'processing','Processing'):'')+b(x,'complete','Complete','')+b(x,'fail','Fail')+b(x,'refund','Refund'):''}</td></tr>`))},
reserves:()=>{const d=S.adm.reserves;if(!d)return loading;
  return`<div class="card"><b>Record reserve movement</b><p class="mut">Record only crypto actually held in a business custody account you control and are authorized to use for customer deliveries.</p><form onsubmit="A.resAdd(event)"><div class="two"><div><label>Asset / network</label><select name="an"><option>USDT|TRC20</option><option>USDT|ERC20</option><option>USDT|BEP20</option><option>BTC|BTC</option></select></div><div><label>Direction</label><select name="direction"><option value="in">Funding in</option><option value="out">Adjustment out</option></select></div></div><label>Amount</label><input name="amount" required inputmode="decimal"><label>Tx hash (optional)</label><input name="txHash" class="mono"><label>Source / memo</label><input name="memo" required maxlength="300"><div class="err"></div><button class="btn" type="submit">Record</button></form></div>
  <div class="grid">${d.reserves.map(r=>tile(`${r.asset} · ${r.network}`,r.balance)).join('')}</div>`+tbl(['#','Date','Asset','Dir','Amount','Tx','Memo','By'],d.movements.map(m=>`<tr><td>${m.id}</td><td>${dt(m.createdAt)}</td><td>${esc(m.asset)} ${esc(m.network)}</td><td>${esc(m.direction)}</td><td>${esc((m.baseUnits/10**(m.asset==='BTC'?8:6)).toString())}</td><td class="mono">${esc(m.txHash||'')}</td><td>${esc(m.memo)}</td><td>${esc(m.actorEmail||'')}</td></tr>`))},
customers:()=>{const c=S.adm.customers||[],x=S.adm.cust;
  return`<div class="card"><form onsubmit="A.custSearch(event)"><label>Search customers (email, name or id)</label><div class="two"><input name="q" value="${esc(S.adm.custQ||'')}"><button class="btn" type="submit">Search</button></div></form></div>`+
  (x?`<div class="card"><b>${esc(x.profile.fullName||x.profile.email)}</b><p class="mut">${esc(x.profile.email)} · ${esc(x.profile.userId)}</p>${x.balances.map(b=>`<div class="row"><span>${esc(b.currency==='IPC'?'IP Coins':b.currency+' credits')}</span><b>${b.currency==='IPC'?nc(b.availableMinor):fmt(b.availableMinor,b.currency)}</b></div>`).join('')}<button class="btn ghost sm" onclick="A.custClose()">Back to results</button></div>
   <h2>Coin purchases</h2><div class="card">${x.coinOrders.map(ordRow).join('')||'<p class="mut">None</p>'}</div><h2>Crypto purchases</h2><div class="card">${x.redemptions.map(redRow).join('')||'<p class="mut">None</p>'}</div>
   <h2>Ledger</h2>`+tbl(['#','Date','Account','Kind','Amount','Memo'],x.ledger.map(e=>`<tr><td>${e.id}</td><td>${dt(e.createdAt)}</td><td>${esc(e.account)}</td><td>${esc(e.kind)}</td><td><b>${e.direction==='debit'?'−':'+'}${e.currency==='IPC'?nc(e.amountMinor)+' IPC':fmt(e.amountMinor,e.currency)}</b></td><td>${esc(e.memo)}</td></tr>`))
   :tbl(['Customer','Joined','IP Coins','Credits',''],c.map(p=>`<tr><td><b>${esc(p.fullName||'—')}</b><div class="mut">${esc(p.email)}</div></td><td>${dt(p.createdAt)}</td><td>${nc(p.coins)}</td><td>${fmt(p.credits)}</td><td><button class="btn sm" onclick="A.custOpen('${esc(p.userId)}')">Open</button></td></tr>`)))},
});
Object.assign(A,{
 async redAct(id,action){const body={};if(action==='complete'){const h=prompt('Enter the blockchain transaction hash of the delivery:');if(!h)return;body.txHash=h.trim();const r=S.adm.redemptions.find(x=>x.id===id);if(r&&r.network!=='BTC'){if(!confirm('No automatic verifier for '+r.network+'. Confirm you verified this transaction on a block explorer (correct wallet, amount, confirmed).'))return;body.attest=true}const ref=prompt('Fulfillment / custody reference (optional):');if(ref)body.fulfillmentReference=ref}
  if(action==='fail'||action==='refund'){const r=prompt('Reason (coins are returned to the customer):');if(!r)return;body.reason=r}if(action==='processing'&&!confirm('Mark as processing?'))return;
  try{await api(`/api/admin/redemptions/${id}/${action}`,{method:'POST',body});toast('Redemption updated','ok');await loadAdm();render()}catch(e){toast(e.message,'bad')}},
 async resAdd(e){e.preventDefault();const f=e.target;const[asset,network]=f.an.value.split('|');busy(f,true);try{await api('/api/admin/reserves',{method:'POST',body:{asset,network,direction:f.direction.value,amount:f.amount.value,txHash:f.txHash.value,memo:f.memo.value}});toast('Reserve recorded','ok');await loadAdm();render()}catch(err){showErr(f,err.message)}finally{busy(f,false)}},
 async custSearch(e){e.preventDefault();S.adm.custQ=e.target.q.value;S.adm.cust=null;S.adm.customers=(await api('/api/admin/customers?q='+encodeURIComponent(S.adm.custQ))).customers;render()},
 async custOpen(id){try{S.adm.cust=await api('/api/admin/customers/'+encodeURIComponent(id));render()}catch(e){toast(e.message,'bad')}},
 custClose(){S.adm.cust=null;render()},
});
// ---------- boot ----------
(async()=>{
  try{const r=await ID.handleAuthCallback();if(r){if(r.type==='recovery'){S.recovery=true;history.replaceState(null,'','#account')}else if(r.type==='confirmation'){toast('Email verified — welcome to Island Pay!','ok');history.replaceState(null,'','#home')}else if(r.type==='invite'){toast('Invite links: set your password via “Forgot your password?”');history.replaceState(null,'','#account')}else history.replaceState(null,'','#home')}}catch(e){toast(authMsg(e),'bad')}
  S.user=await ID.getUser().catch(()=>null);
  ID.onAuthChange((ev,u)=>{if(ev===ID.AUTH_EVENTS.TOKEN_REFRESH)return;S.user=u;if(!u){S.me=null;S.deps=null}route()});
  addEventListener('hashchange',route);await route();
  try{if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('/sw.js').catch(()=>{})}catch{}
})();
